using System.IO;using System.Reflection;using System.Security.Cryptography;using System.Text.Json;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using RAWSelectionAssistant.Core.Services.Projects;using RAWSelectionAssistant.ViewModels;using RAWSelectionAssistant.Views;using RAWSelectionAssistant.Services;using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public class R54DevelopedStageTests
{
 static string Root()=>Environment.GetEnvironmentVariable("KITAO_STAGE_IDENTITY")??throw new InvalidOperationException("explicit root");
 static string Hash(BitmapSource image){var b=new FormatConvertedBitmap(image,PixelFormats.Bgra32,null,0);var bytes=new byte[b.PixelWidth*b.PixelHeight*4];b.CopyPixels(bytes,b.PixelWidth*4,0);return Convert.ToHexString(SHA256.HashData(bytes));}
 static void Layout(FrameworkElement v){v.Measure(new Size(1366,768));v.Arrange(new Rect(0,0,1366,768));v.UpdateLayout();}
 static void Invoke(PhotoGradePageView v,string name){var method=typeof(PhotoGradePageView).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance)!;method.Invoke(v,method.GetParameters().Length==0?null:[v,new RoutedEventArgs()]);}
 static string Image(string root){Directory.CreateDirectory(root);var a=new byte[96*64*3];for(int i=0;i<a.Length;i++)a[i]=(byte)(i%251);var b=BitmapSource.Create(96,64,96,96,PixelFormats.Rgb24,null,a,288);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));var path=Path.Combine(root,"stage-input.png");using var f=File.Create(path);e.Save(f);return path;}
 static async Task Settle(TetherReferenceModeViewModel editor){var end=DateTime.UtcNow.AddSeconds(30);while(!editor.IsSettled&&DateTime.UtcNow<end)await Task.Delay(15);Assert.IsTrue(editor.IsSettled);}
 [TestMethod]public Task FrozenStageIdentitySurvivesSelectionWindowAndReshoot()=>RunSta(async()=>
 {
  EnsureTestApplication();var root=Root();using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());await vm.LoadTargetAsync(Image(root));vm.EnableLightPrintWorkspace();vm.InstantCameraAnimation=false;var page=new PhotoGradePageView{DataContext=vm};Layout(page);vm.R53Professional=true;vm.Layout=vm.Layout with{R54GraphCollapsed=false};page.DataContext=null;page.DataContext=vm;Layout(page);var graph=(StudioNodeGraphView)((Grid)page.FindName("R53NodeContent")).Children[0];Assert.IsNull(graph.Stage);
  vm.SelectedLightPrintFrameId="orig.01";await vm.LightPrintPreviewWork;Assert.IsNull(graph.Stage);await vm.DevelopLightPrintCommand.ExecuteAsync(null);Assert.IsTrue(vm.IsLightPrintLocked,vm.LightPrintStatus);graph.RefreshDevelopedStage();graph.Fit();Layout(page);var screenshot=new RenderTargetBitmap(1366,768,96,96,PixelFormats.Pbgra32);screenshot.Render(page);var capture=new PngBitmapEncoder();capture.Frames.Add(BitmapFrame.Create(screenshot));using(var screenshotFile=File.Create(Path.Combine(root,"developed-stage-1366-OFFSCREEN.png")))capture.Save(screenshotFile);var stage=graph.Stage;Assert.IsNotNull(stage);Assert.AreEqual(vm.ActiveTarget!.ActiveEditVersionId,stage.VariantId);Assert.AreEqual(vm.ActiveTarget.RawDefinition!.InstantInput?.OriginVersionId,stage.SourceVariantId);Assert.AreEqual(stage,DevelopedStageProjection.FromCommitted(stage.VariantId,vm.ActiveTarget.RawDefinition));Assert.IsNull(DevelopedStageProjection.FromCommitted(stage.VariantId,vm.ActiveTarget.RawDefinition,true));
  var before=JsonSerializer.Serialize(vm.ActiveTarget.RawDefinition);var pixels=Hash(vm.Editor.MatchedImage!);var positions=vm.Editor.GraphView.Positions;var pos=new Point(80,80);Assert.IsTrue(graph.SelectStageAt(pos));graph.ExecuteGraphKey(System.Windows.Input.Key.Delete,System.Windows.Input.ModifierKeys.None);graph.ExecuteGraphKey(System.Windows.Input.Key.F2,System.Windows.Input.ModifierKeys.None);Assert.AreEqual(before,JsonSerializer.Serialize(vm.ActiveTarget.RawDefinition));Assert.AreEqual(pixels,Hash(vm.Editor.MatchedImage!));
  foreach(var w in Application.Current.Windows.OfType<Window>().Where(w=>w.Title=="光镜 · 冻结显影配方").ToArray()){var text=((StackPanel)w.Content).Children.OfType<TextBox>().Single();Assert.IsTrue(text.IsReadOnly);Assert.AreEqual(stage.FrozenRecipeJson,text.Text);w.Close();}
  var file=Path.Combine(root,"stage.ptstudio.json");await vm.SaveSessionAsync(file);await File.WriteAllTextAsync(Path.Combine(root,"stage-expected.json"),JsonSerializer.Serialize(new{pid=Environment.ProcessId,variant=stage.VariantId,hash=stage.RecipeSha256,definition=before,pixels}));
  vm.Editor.AddAdjustmentNodeCommand.Execute("BasicTone");vm.Editor.SetToolParameter(ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.BasicTone).Single(p=>p.Key=="exposure"),.6);await vm.ApplyWindowGradeCommand.ExecuteAsync(null);Assert.AreEqual(stage.RecipeSha256,DevelopedStageProjection.FromCommitted(stage.VariantId,vm.ActiveTarget.RawDefinition)!.RecipeSha256);var priorVersion=stage.VariantId;var priorRecipe=JsonSerializer.Serialize(vm.ActiveTarget.RawDefinition);vm.ReshootLightPrintCommand.Execute(null);await vm.LightPrintPreviewWork;Assert.IsFalse(vm.IsLightPrintLocked);await vm.DevelopLightPrintCommand.ExecuteAsync(null);Assert.AreNotEqual(priorVersion,vm.ActiveTarget.ActiveEditVersionId);var old=vm.ActiveTarget.EditVersions.Single(v=>v.Id==priorVersion);Assert.AreEqual(priorRecipe,JsonSerializer.Serialize(old.RawDefinition));page.DataContext=null;
 });
 [TestMethod]public Task StageSelectionAndRecipeWindowRetireOnVariantSwitch()=>RunSta(async()=>
 {
  EnsureTestApplication();var root=Path.Combine(Root(),"switch");using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());await vm.LoadTargetAsync(Image(root));vm.EnableLightPrintWorkspace();vm.InstantCameraAnimation=false;await vm.LightPrintPreviewWork;await vm.DevelopLightPrintCommand.ExecuteAsync(null);var developed=vm.ActiveTarget!.ActiveEditVersionId!.Value;var original=vm.ActiveTarget.EditVersions.First(v=>v.IsOriginal).Id;var page=new PhotoGradePageView{DataContext=vm};Layout(page);vm.R53Professional=true;vm.Layout=vm.Layout with{R54GraphCollapsed=false};page.DataContext=null;page.DataContext=vm;Layout(page);var graph=(StudioNodeGraphView)((Grid)page.FindName("R53NodeContent")).Children[0];Assert.IsNotNull(graph.Stage);Assert.IsTrue(graph.SelectStageAt(new Point(80,80)));Assert.AreEqual(0,Application.Current.Windows.OfType<Window>().Count(w=>w.Title=="光镜 · 冻结显影配方"));Assert.IsNotNull(typeof(PhotoGradePageView).GetField("developedSummary",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(page));await vm.SwitchEditVersionAsync(original);Assert.IsNull(graph.Stage);Assert.IsNull(typeof(PhotoGradePageView).GetField("developedSummary",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(page));Assert.AreEqual(0,Application.Current.Windows.OfType<Window>().Count(w=>w.Title=="光镜 · 冻结显影配方"));await vm.SwitchEditVersionAsync(developed);Assert.AreEqual(developed,graph.Stage!.VariantId);var definition=vm.ActiveTarget.RawDefinition!;Assert.ThrowsExactly<InvalidDataException>(()=>DevelopedStageProjection.FromCommitted(developed,definition with{LightPrint=definition.LightPrint! with{Version=999}}));vm.ReshootLightPrintCommand.Execute(null);await vm.LightPrintPreviewWork;Assert.IsNull(graph.Stage);vm.CancelLightPrintPreviewCommand.Execute(null);await vm.LightPrintPreviewWork;Assert.AreEqual(developed,graph.Stage!.VariantId);page.DataContext=null;
 });
 [TestMethod]public Task IndependentStageReopen()=>RunSta(async()=>
 {
  EnsureTestApplication();var root=Root();using var doc=JsonDocument.Parse(await File.ReadAllTextAsync(Path.Combine(root,"stage-expected.json")));var expected=doc.RootElement;Assert.AreNotEqual(Environment.ProcessId,expected.GetProperty("pid").GetInt32());using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs());await vm.LoadSessionAsync(Path.Combine(root,"stage.ptstudio.json"));await Settle(vm.Editor);var stage=DevelopedStageProjection.FromCommitted(vm.ActiveTarget!.ActiveEditVersionId,vm.ActiveTarget.RawDefinition);Assert.IsNotNull(stage);Assert.AreEqual(expected.GetProperty("variant").GetGuid(),stage.VariantId);Assert.AreEqual(expected.GetProperty("hash").GetString(),stage.RecipeSha256);Assert.AreEqual(expected.GetProperty("definition").GetString(),JsonSerializer.Serialize(vm.ActiveTarget.RawDefinition));Assert.AreEqual(expected.GetProperty("pixels").GetString(),Hash(vm.Editor.MatchedImage!));
 });
 sealed class Dialogs:IDialogService{public IReadOnlyList<string> ChooseFiles(string a,string b,bool c)=>[];public string? ChooseFolder(string a,string? b=null)=>null;public string? ChooseSaveFile(string a,string b,string c,string? d=null)=>null;public bool Confirm(string a,string b)=>false;public void ShowInfo(string a){}public void ShowError(string a){}public IReadOnlyList<string>? ManageQuickTools(IReadOnlyList<string>x)=>x;public HelpAction ShowHelp()=>HelpAction.None;public void ShowFeedback(){}public RAWSelectionAssistant.Core.Models.RawFileEntry? ChooseRawCandidate(IReadOnlyList<RAWSelectionAssistant.Core.Models.RawFileEntry>x)=>null;public bool ShowMediaDetails(RAWSelectionAssistant.Core.Models.MediaSelectionItem x,bool y)=>false;public void RevealFile(string p){}}
}
